#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"East zone\n\n  Pier\n"};
    std::string linea;
    int cantidad = 0;
    int vacias = 0;
    while (std::getline(entrada, linea)) {
        ++cantidad;
        if (linea.empty()) {
            ++vacias;
        }
        std::cout << cantidad << ":<" << linea << ">\n";
    }
    std::cout << "Lines: " << cantidad << "\nEmpty: " << vacias;
    return 0;
}

